INSERT INTO public.products (name, slug, sku, category_id, brand, short_description, description, price_npr, discount_price_npr, stock_qty, low_stock_threshold, image_url, images, variant_label, variant_options, tags, is_active, is_featured) VALUES
    ('Plum 5% Glycolic Acid & Goji Berry Exfoliating Toner', 'plum-5-glycolic-acid-goji-berry-exfoliating-toner', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Plum', 'Plum 5% Glycolic Acid & Goji Berry Exfoliating Toner gently exfoliates to help smooth rough texture, unclog pores, and improve dull-looking skin. Formulated with 5% Glycolic Acid and Goji Berry for a smoother, brighter-looking complexion.', 'Plum 5% Glycolic Acid & Goji Berry Exfoliating Toner is a gentle exfoliating toner designed to improve the appearance of textured, dull, and uneven-looking skin. Formulated with 5% Glycolic Acid and Goji Berry, it helps gently remove dead skin cells, refine skin texture, and reveal a smoother, brighter-looking complexion over time.

The exfoliating formula helps unclog pores and reduce the appearance of congestion while supporting smoother-looking skin. It is a great addition to a skincare routine focused on improving rough texture and dullness.

Key Benefits:

• Contains 5% Glycolic Acid

• Helps smooth rough and bumpy skin texture

• Helps remove dead skin cells

• Helps unclog pores and reduce congestion

• Helps improve dull-looking skin

• Promotes a brighter, smoother-looking complexion

• Formulated with Goji Berry

• Helps reduce post-exfoliation dryness', 795, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-5-Glycolic-Acid-Goji-Berry-Exfoliating-Toner.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-5-Glycolic-Acid-Goji-Berry-Exfoliating-Toner.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["toner"]'::jsonb, TRUE, TRUE),
    ('Plum Bulgarian Valley Rose Water Toner 100ml', 'plum-bulgarian-valley-rose-water-toner-100ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Plum', 'Plum Bulgarian Valley Rose Water Toner 100ml is an alcohol-free, refreshing face toner that hydrates, soothes, and helps balance the skin. It also helps minimize the appearance of pores while leaving skin feeling fresh and plump.', 'Plum Bulgarian Valley Rose Water Toner 100ml is an alcohol-free, daily-use face toner that helps hydrate and balance the skin while providing an instant refreshing feel. Enriched with Bulgarian Valley Rose Water, it is designed to leave the skin feeling fresh, soft, and comfortable.

The lightweight toner helps replenish moisture, soothe the skin, and support a balanced-looking complexion. Regular use can also help minimize the appearance of pores, making it an easy addition to your daily skincare routine.

Key Benefits:

• Provides lightweight hydration

• Helps plump and refresh the skin

• Soothes and balances the skin

• Helps maintain skin pH balance

• Helps minimize the appearance of pores

• Alcohol-free formula

• Suitable for daily use

• Leaves skin feeling fresh and comfortable', 405, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-Bulgarian-Valley-Rose-Water-Toner-100ml.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-Bulgarian-Valley-Rose-Water-Toner-100ml.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["rose water","rose water toner"]'::jsonb, TRUE, FALSE),
    ('Plum Rice Water & 3% Niacinamide Sheer Tinted Sunscreen', 'plum-rice-water-3-niacinamide-sheer-tinted-sunscreen', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Plum', 'Plum Rice Water & 3% Niacinamide Sheer Tinted Sunscreen combines daily sun protection with a lightweight sheer tint for a natural, even-looking finish. Formulated with Rice Water and 3% Niacinamide, it is ideal for everyday use.', 'Plum Rice Water & 3% Niacinamide Sheer Tinted Sunscreen is a lightweight tinted sunscreen designed to provide everyday sun protection while giving the skin a more even and naturally radiant-looking appearance. Formulated with Rice Water and 3% Niacinamide, it combines sun protection with skincare benefits in an easy-to-wear formula.

The sheer tint helps provide a subtle, natural-looking finish, making it suitable for everyday use when you want lightweight coverage without the feel of a heavy base. Its skin-friendly formula can be easily incorporated into your morning skincare and makeup routine.

Key Benefits:

• Provides everyday sun protection

• Sheer tinted formula for a natural-looking finish

• Formulated with Rice Water

• Contains 3% Niacinamide

• Helps give skin a more even-looking appearance

• Lightweight and comfortable for daily wear

• Can be worn alone or under makeup', 795, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-Rice-Water-3-Niacinamide-Sheer-Tinted-Sunscreen.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-Rice-Water-3-Niacinamide-Sheer-Tinted-Sunscreen.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Sunscreen","Tinted Sunscreen"]'::jsonb, TRUE, FALSE),
    ('Plum 15% Vitamin C Face Serum with Mandarin 30ml', 'plum-15-vitamin-c-face-serum-with-mandarin-30ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Plum', 'Plum 15% Vitamin C Face Serum with Mandarin is a lightweight brightening serum that helps give dull-looking skin a fresh, radiant glow. Apply a few drops to cleansed face and neck and gently pat into the skin.', 'Plum 15% Vitamin C Face Serum with Mandarin 30ml is a brightening face serum designed to give your skin a fresh, radiant-looking appearance. Formulated with 15% Vitamin C and Mandarin, it is a great addition to a skincare routine focused on improving dull-looking skin and boosting glow.

Its lightweight serum texture makes it easy to apply and layer with the rest of your skincare routine. For best use, apply a few drops to clean skin and gently pat it into the face and neck.

Key Benefits:

• Contains 15% Vitamin C

• Helps brighten dull-looking skin

• Promotes a fresh, radiant-looking glow

• Lightweight serum texture

• Easy to layer into your daily skincare routine

• Suitable for use on the face and neck

• Comes with a convenient dropper applicator', 1260, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-15-Vitamin-C-Face-Serum-with-Mandarin-30ml.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Plum-15-Vitamin-C-Face-Serum-with-Mandarin-30ml.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Face Serum","Serum"]'::jsonb, TRUE, FALSE),
    ('Dr.Althea PDRN Reju 5000 Cream', 'dr-althea-pdrn-reju-5000-cream', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Dr.Althea', 'Dr.Althea PDRN Reju 5000 Cream is a lightweight, nourishing face cream with 5,000 ppm probiotic-derived vegan PDRN that hydrates dry, dull-looking skin and leaves it feeling soft, comfortable, and fresh with a healthy-looking glow.', 'Dr.Althea PDRN Reju 5000 Cream is a nourishing face cream designed for dry, dull-looking skin that needs moisture, softness, and a healthy-looking glow. Formulated with 5,000 ppm probiotic-derived vegan PDRN from five fermented ingredients, it helps replenish moisture and leave the skin feeling comfortable and hydrated.

The lightweight, layerable texture provides nourishing hydration without leaving a heavy or greasy finish. You can adjust the amount based on your skin’s needs, making it suitable for everyday moisturizing and more intensive hydration when your skin feels dry or uncomfortable.', 2350, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Dr.Althea-PDRN-Reju-5000-Cream.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Dr.Althea-PDRN-Reju-5000-Cream.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Face Cream"]'::jsonb, TRUE, FALSE),
    ('Dr. Althea Melaclear Cream', 'dr-althea-melaclear-cream', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Dr. Althea', 'Dr. Althea Melaclear Cream is a brightening face cream with tranexamic acid and niacinamide that helps improve the appearance of dark spots, post-blemish marks, and uneven skin tone while keeping skin moisturized.', 'Dr. Althea Melaclear Cream is a brightening face cream formulated with tranexamic acid and niacinamide to help improve the appearance of dark spots, post-blemish marks, and uneven-looking skin tone. Its moisturizing formula provides brightening care while helping keep the skin feeling soft and hydrated.

With a lightweight cream-to-serum texture, Dr. Althea Melaclear Cream can be applied directly to specific areas of discoloration or used as an overnight brightening moisture layer for more intensive care.', 2220, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/Dr.-Althea-Melaclear-Cream.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/Dr.-Althea-Melaclear-Cream.jpeg"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('La Roche-Posay Cicaplast Baume B5+', 'la-roche-posay-cicaplast-baume-b5', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), NULL, 'La Roche-Posay Cicaplast Baume B5+ is a multi-purpose repairing balm that soothes, protects, and helps restore irritated, dry, or weakened skin. With a nourishing, non-greasy texture, it can be used on the face, body, and lips by the whole', 'La Roche-Posay Cicaplast Baume B5+ is a dermatologist-tested, multi-purpose repairing balm designed to soothe, protect, and restore irritated or weakened skin. Suitable for the whole family, this nourishing balm helps support skin barrier recovery while providing comfort to dry, sensitive, and irritated skin.

Formulated for everyday skin repair, Cicaplast Baume B5+ helps soothe redness, dryness, irritation, and discomfort while protecting the skin with a nourishing yet non-greasy, fast-absorbing texture.

This versatile repair balm can be used on the face, body, and lips and is suitable for various skin concerns, including burns, mosquito bites, post-procedure skin, and nappy rash.', 3850, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/La-Roche-Posay-Cicaplast-Baume-B5.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/La-Roche-Posay-Cicaplast-Baume-B5.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["skin repair"]'::jsonb, TRUE, FALSE),
    ('CeraVe Invisible Mineral Sunscreen SPF 50', 'cerave-invisible-mineral-sunscreen-spf-50', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'CeraVe', 'CeraVe Invisible Mineral Sunscreen SPF 50 provides lightweight, hydrating broad-spectrum UVA/UVB protection with a more transparent finish across a wide range of skin tones. Suitable for sensitive and acne-prone skin, its mineral formula gl', 'CeraVe Invisible Mineral Sunscreen SPF 50 is a lightweight, hydrating mineral sunscreen designed to provide broad-spectrum protection against UVA and UVB rays. Formulated with CeraVe’s miner-ALL technology, it is designed to leave a more transparent finish across a wide range of skin tones and types, including sensitive and acne-prone skin.

Its weightless formula glides smoothly onto the skin without feeling heavy, making it suitable for everyday sun protection. The sunscreen is also designed to blend more transparently on beards, making it a convenient option for a wide range of users.', 2950, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/09/CeraVe-Invisible-Mineral-Sunscreen-SPF-50.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/09/CeraVe-Invisible-Mineral-Sunscreen-SPF-50.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Mineral Sunscreen","Sunscreen"]'::jsonb, TRUE, FALSE),
    ('Loreal Professionnel Serie Expert Liss Unlimited Mask', 'loreal-professionnel-serie-expert-liss-unlimited-mask', NULL, (SELECT id FROM public.product_categories WHERE slug = 'hair-care'), 'Loreal', 'Smoothing hair mask for rebellious hair. Blocks humidity to control frizz, adds shine, and leaves hair smooth and manageable. Ideal for all hair types, especially rebellious or straightened hair.', 'Tame rebellious, frizz-prone hair with L’Oréal Professionnel Serie Expert Liss Unlimited Masque. This luxurious smoothing mask nourishes and coats each hair fiber, polishing its surface while forming an effective barrier against humidity — so your style stays smooth even in humid conditions.

Hair is left bathed in hydration, with enhanced shine and regained control over frizz. The result is smoother, more manageable hair that resists humidity-triggered puffiness, making it a great fit for anyone with unruly, frizz-prone, or straightened hair looking to maintain a sleek finish.

Key Benefits:

Anti-frizz protection

Purifies and smoothens hair fiber

Effective humidity blocker

Enhanced shine

Nourishes and hydrates hair', 1585, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Professionnel-Serie-Expert-Liss-Unlimited-Mask.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Professionnel-Serie-Expert-Liss-Unlimited-Mask.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Hair Mask"]'::jsonb, TRUE, FALSE),
    ('Loreal Professionnel Serie Expert Inforcer Shampoo', 'loreal-professionnel-serie-expert-inforcer-shampoo', NULL, (SELECT id FROM public.product_categories WHERE slug = 'hair-care'), 'Loreal', 'Strengthening anti-breakage shampoo with Vitamin B6 & Biotin. Delivers up to 8X less breakage with continued use, leaving hair stronger, smoother, and more resistant to damage. Ideal for weak, breakage-prone hair.', 'Reinforce weak, breakage-prone hair with L’Oréal Professionnel Serie Expert Inforcer Shampoo. Formulated with Vitamin B6 and Biotin, this strengthening shampoo works to reduce breakage instantly while nourishing each hair strand from root to tip for healthier, more resilient hair.

Vitamin B6 strengthens hair follicles from within, while Biotin nourishes the scalp and supports stronger, thicker hair growth. Together, they help restore your hair’s natural vitality, resulting in noticeably less breakage and improved overall strength.

With consistent use, hair becomes up to 8X more resistant to breakage, softer, smoother, and easier to manage — with reduced tangling for a smoother, hassle-free styling experience every time.

Key Benefits:

• Up to 8X less breakage with continued use*

• Strengthens hair from root to tip

• Improved hydration and nourishment

• Softer, smoother, more manageable hair

• Easier combing, reduced tangling

• Infused with Vitamin B6 & Biotin', 1200, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/LOreal-Professionnel-Serie-Expert-Inforcer-Shampoo.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/LOreal-Professionnel-Serie-Expert-Inforcer-Shampoo.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["shampoo"]'::jsonb, TRUE, FALSE),
    ('Loreal Professionnel Serie Expert Inforcer Mask', 'loreal-professionnel-serie-expert-inforcer-mask', NULL, (SELECT id FROM public.product_categories WHERE slug = 'hair-care'), 'Loreal', 'Reinforcing hair mask with Vitamin B6 & Biotin for instant reduced breakage and intense conditioning. Strengthens hair, making it more resistant with continued use. Ideal for weak, breakage-prone hair.', 'Give your hair the strength it needs with L’Oréal Professionnel Serie Expert Inforcer Mask. This indulgent reinforcing formula is infused with Vitamin B6 and Biotin, working to instantly reduce breakage while delivering intense conditioning from root to tip.

With continued use, hair becomes noticeably more resistant and stronger, better equipped to handle daily styling and stress. The rich, conditioning texture leaves hair feeling nourished, smooth, and more resilient — perfect for anyone dealing with weak, fragile, or breakage-prone hair.

Key Benefits:

Instantly reduces hair breakage

Infused with Vitamin B6 & Biotin

Intense conditioning action

Strengthens and reinforces hair with continued use

Ideal for weak, fragile hair

Hair Type: Weak, brittle, or breakage-prone hair', 1585, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Serie-Expert-Inforcer.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Serie-Expert-Inforcer.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Hair Mask","Hair Masque"]'::jsonb, TRUE, FALSE),
    ('Loreal Professionnel Serie Expert Vitamino Color Resveratrol Masque 250ml', 'loreal-professionnel-serie-expert-vitamino-color-resveratrol-masque-250ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'hair-care'), 'Loreal', 'Color-protecting mask with Resveratrol & Panthenol for salon-colored hair. Delivers up to 8 weeks of color protection and 5X more shine, while strengthening hair from roots to tips.', 'Keep your salon-colored hair vibrant and healthy with L’Oréal Professionnel Serie Expert Vitamino Color Mask. Infused with Resveratrol, Panthenol, and other nourishing ingredients, this color radiance mask gently cleanses impurities while giving your color-treated hair the protection it needs to stay radiant for longer.

Its creamy texture transforms into a rich foam on application, working to strengthen the hair fiber from roots to tips while helping to lock in color vibrancy. With regular use, hair looks more radiant, feels stronger, and holds onto its salon color longer between treatments.

Key Benefits:

• Up to 8 weeks of color protection*

• 5X more shine

• Strengthens hair fiber from roots to tips

• Creamy-to-foam texture for gentle, effective cleansing

• Infused with Resveratrol & Panthenol

*Instrumental test: shampoo + mask vs. non-conditioning shampoo, used with the nourishing L’Oréal Professionnel Vitamino Color mask.', 1585, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Vitamino-color-Reseratrol-Professional-Mask.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Loreal-Vitamino-color-Reseratrol-Professional-Mask.jpeg"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, TRUE),
    ('Loreal Professionnel Serie Expert Absolut Repair Mask &#8211; With Protein & Omega-9', 'loreal-professionnel-serie-expert-absolut-repair-mask-with-protein-omega-9', NULL, (SELECT id FROM public.product_categories WHERE slug = 'hair-care'), 'Loreal', 'Deep-repair hair mask powered by Protein & Omega-9. Strengthens damaged hair fiber, boosts shine, and leaves hair soft and lightweight with up to 13X more resistance. Vegan formula.', 'Give damaged hair the intensive care it needs with L’Oréal Professionnel Serie Expert Absolut Repair Mask. Formulated with Protein & Omega-9, this expert nourishing mask works deep within the hair fiber to repair damage, restore strength, and lock in hydration — leaving hair soft, smooth, and visibly healthier with every use.

Regular use helps hair withstand daily stress and styling damage, while enhancing natural shine and manageability. The lightweight formula absorbs easily without weighing hair down, making it suitable for regular use on dry, brittle, or chemically treated hair.

Key Benefits:

• Up to 13X more resistance to damage

• Boosts hair shine

• Lightweight, non-greasy finish

• Softer, smoother hair with continued use

• Vegan formula — no animal-derived ingredients or by-products', 1585, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Absolut-Repair-Protein-and-Omega-9.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Absolut-Repair-Protein-and-Omega-9.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Hair Mask"]'::jsonb, TRUE, FALSE),
    ('Banana Boat Kids Sensitive Mineral Based Sunscreen', 'banana-boat-kids-sensitive-mineral-based-sunscreen', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Banana', 'Gentle mineral sunscreen made for kids’ sensitive skin. SPF 50 PA+++ broad-spectrum UVA/UVB protection, waterproof and sweat-resistant, with no eye-stinging formula. Free from oxybenzone, parabens, oils, and added fragrance.', 'Keep your little ones protected during every outdoor adventure with Banana Boat Kids Sensitive Mineral Based Sunscreen SPF 50 PA+++. Specially formulated for children’s delicate skin, this mineral-based sunscreen offers powerful broad-spectrum protection against both UVA and UVB rays, helping shield young skin from sunburn and long-term sun damage.

Unlike many regular sunscreens, this gentle formula won’t sting or irritate the eyes, making it ideal for active kids who run, swim, and play without a break. It’s highly water-resistant and sweat-proof, so protection stays strong through swimming, sports, and hot, humid days.

Formulated with 25% fewer chemicals and free from oxybenzone, parabens, added oils, and perfumes, it’s a safer choice for sensitive young skin. Suitable for use on both the face and body, it blends easily and is designed for everyday outdoor use — beach days, school sports, or simple playtime outside.

Key Highlights:

• SPF 50 PA+++ broad-spectrum UVA/UVB protection

• Mineral-based, gentle sensitive-skin formula

• No eye-stinging, kid-friendly application

• Waterproof and sweat-resistant

• 25% fewer chemicals

• Free from oxybenzone, parabens, oils, and perfume

• Safe for face and body use', 1125, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Sunscreen-for-Kids.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Sunscreen-for-Kids.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Child Sunscreen","Kids Sunscreen","Sunscreen for kids","Sunscreen Kids"]'::jsonb, TRUE, FALSE),
    ('Maybelline Lash Sensational Sky High Waterproof Mascara', 'maybelline-lash-sensational-sky-high-waterproof-mascara', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Maybelline', 'Achieve sky-high, dramatic lashes with Maybelline Lash Sensational Sky High Waterproof Mascara. This buildable formula is infused with nourishing bamboo extract and fibres for fuller, longer-looking lashes. Lightweight, flake-free, and wate', 'Elevate your lash game with Maybelline’s Lash Sensational Sky High Waterproof Mascara — designed to deliver dramatic, sky-high length and volume without the weight. Whether you’re after a natural everyday look or bold, voluminous lashes, this buildable formula adapts to your desired intensity.

Key Benefits:

• Bamboo Extract & Fibre-Infused Formula: Nourishes lashes while building fullness and length with every coat, for a fuller, more voluminous lash line.

• Limitless Lengthening & Volume: The uniquely designed brush captures and coats lashes from root to tip, reaching even the shortest and hardest-to-reach hairs from every angle.

• Lightweight, Non-Weighing Formula: Delivers big, bold volume without feeling heavy or clumpy, so lashes stay lifted and comfortable all day.

• Richly Pigmented, Flake-Free Colour: Intense, true black pigment glides on smoothly and stays put without flaking or smudging.

• Defining, Curling & Multiplying Effect: Separates and curls each lash while visually multiplying lash density for a fuller fringe.

• Waterproof Formula: Long-lasting wear that resists smudging, sweat, humidity, and tears — ideal for all-day and all-weather confidence.

Who It’s For:

Suitable for all lash types, this mascara is perfect for anyone wanting buildable, customizable volume and length — from a subtle daytime flutter to a bold, statement-making lash look.

How to Use:

Starting at the base of your lashes, wiggle the brush upward through to the tips. Layer additional coats for extra volume and length, allowing lashes to dry slightly between applications for maximum buildability.', 1850, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Maybelline-Lash-Sensational-Sky-High-Waterproof-Mascara.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Maybelline-Lash-Sensational-Sky-High-Waterproof-Mascara.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["waterproof mascara"]'::jsonb, TRUE, FALSE),
    ('CeraVe Moisturizing Cream With Pump 453g', 'cerave-moisturizing-cream-with-pump-453g', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'CeraVe', 'Hydrate and repair your skin barrier with CeraVe Moisturizing Cream (453g). Formulated with 3 essential ceramides, hyaluronic acid, and MVE Technology for 24-hour moisture release. Non-greasy, fragrance-free, and dermatologist-developed for', 'Give your skin the deep, lasting hydration it deserves with CeraVe Moisturizing Cream. Developed alongside dermatologists, this rich yet non-greasy formula is designed to restore and maintain your skin’s natural protective barrier while delivering intense moisture that lasts all day and night.

Key Benefits:

• 3 Essential Ceramides (1, 3, 6-II): Help restore and strengthen the skin’s natural barrier, protecting against moisture loss and environmental stressors.

• Hyaluronic Acid: Attracts and retains moisture, keeping skin plump, smooth, and hydrated.

• MVE Technology: A patented time-release delivery system that continuously releases moisturizing ingredients over 24 hours, so you’re not constantly reapplying.

• Non-Greasy, Fast-Absorbing Formula: Sinks in quickly without leaving a heavy or oily residue, making it comfortable for everyday wear.

• Fragrance-Free: Gentle enough for sensitive skin, with no added fragrances that could cause irritation.

Who It’s For:

Ideal for those with dry to very dry skin, this versatile cream can be used on both the face and body. Its gentle, dermatologist-approved formula helps soothe dryness, calm irritation, and support overall skin health — making it suitable for daily use by the whole family.

Why Choose the Pump Format:

The 453g pump dispenser makes application easy, hygienic, and mess-free — perfect for daily use in the bathroom or by the bedside, ensuring you get the right amount every time without waste.

How to Use:

Apply liberally to face and body as often as needed, especially after bathing or showering, to lock in moisture and keep skin feeling soft, smooth, and comfortable throughout the day.', 3950, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Cerave-Moisturizing-Cream-453-gm-With-Pump.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Cerave-Moisturizing-Cream-453-gm-With-Pump.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["cerave","moisturizing cream"]'::jsonb, TRUE, FALSE),
    ('Maybelline Lash Sensational Sky High Washable Mascara', 'maybelline-lash-sensational-sky-high-washable-mascara', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Maybelline', 'Get limitless length and full volume with Maybelline Lash Sensational Sky High Washable Mascara. The Flex Tower brush bends to coat every lash from root to tip, while the bamboo and fiber-infused formula delivers a lightweight, buildable lo', 'Reach new heights with the Maybelline Lash Sensational Sky High Washable Mascara — a formula built to give your lashes dramatic length, full volume, and stunning definition from every angle. At the heart of this mascara is the exclusive Flex Tower brush, designed to flex and bend as you apply, ensuring every lash — even the hard-to-reach corner lashes — gets evenly coated with pigment from base to tip.

Infused with bamboo extract and fine fibers, the lightweight formula wraps each lash for visible length without weighing them down or feeling stiff. The intensely pigmented &#8216;Very Black’ shade delivers bold, impactful color for a striking, wide-eyed look that lasts all day.

Best of all, this mascara is fully washable — no harsh rubbing, no makeup remover needed. Just rinse with warm water for effortless, gentle removal that’s kind to your lashes.

Key Highlights:

Exclusive Flex Tower brush bends to coat every lash

Bamboo extract and fiber-infused formula for lightweight length

Rich, pigmented &#8216;Very Black’ shade for bold definition

Washable formula rinses away cleanly with water alone', 1850, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/08/Maybelline-Mascara-Washable.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2026/08/Maybelline-Mascara-Washable.jpeg"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Bellaoggi Moisturising Lotion', 'bellaoggi-moisturising-lotion', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Bellaoggi', 'Bellaoggi Moisturising Lotion is a rich, thick fluid that instantly hydrates the skin, leaving it soft, firm and radiant. Ideal for daily face and neck care.', 'Bellaoggi Moisturising Lotion is a rich, thick fluid formulated to hydrate the skin immediately on application. Lightweight yet nourishing, it leaves the complexion feeling soft, looking firm, and visibly radiant with regular use.

Designed for daily use on the face and neck, this lotion works to replenish moisture and support a healthy, glowing appearance, making it an easy addition to any skincare routine.

Key Features:

Instant Hydration — rich, thick formula absorbs to moisturise on contact

Soft, Firm Skin — supports a smoother, firmer-looking complexion

Radiant Finish — leaves skin looking healthy and glowing

Face & Neck Use — suitable for daily application

How to Use:

Apply to the face and neck using a cotton pad or directly with the fingers, patting gently. Avoid the eye contour area.', 3350, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/07/Bellaoggi-MOISTURIZING-LOTION.png', '["https://colorpluscosmetics.com/wp-content/uploads/2026/07/Bellaoggi-MOISTURIZING-LOTION.png"]'::jsonb, NULL, '[]'::jsonb, '["daily moisturiser","moisturising lotion"]'::jsonb, TRUE, FALSE),
    ('Bellaoggi Lumi Gloss', 'bellaoggi-lumi-gloss', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Bellaoggi', 'Bellaoggi Lumi Gloss is a universal top coat that adds a shimmering, three-dimensional finish to any lipstick. Non-sticky and enriched with Vitamin E, Omega 3 and Omega 6, it hydrates lips while delivering a high-shine, glam sparkle.', 'Bellaoggi Lumi Gloss is a brand-new universal top coat designed to give any lipstick a fresh shimmer finish, making lips ultra-glam and sparkling. It works as the perfect finishing touch to bring new light to the lips, emphasize colour, and enhance volume.

Formulated with a non-sticky texture and a very high emollient power, Lumi Gloss is enriched with Vitamin E, Omega 3 and Omega 6 to hydrate and protect the lips with every application. Worn alone, it delivers a touch of light with a three-dimensional effect and a super-shiny finish.

Sweetly scented with vanilla, Lumi Gloss features an extremely flexible texture that allows for a modulated colour effect — choose between pure luminosity or full coverage of reflective pearls, depending on the look you’re after. For lips that are highly seductive and irresistibly glossy, this lip topper is the finishing step every lipstick collection needs.

Key Features:

Universal Top Coat — layers over any lipstick shade

Non-Sticky Formula — comfortable, high-emollient texture

Hydrating & Protective — enriched with Vitamin E, Omega 3 & Omega 6

3D Shine Effect — super-glossy, reflective finish

Customisable Coverage — from sheer luminosity to full pearl reflection

Vanilla Scented — subtly sweet fragrance

How to Use:

Apply over your favourite lipstick shade, or wear alone for a glossy, shimmering finish.', 1750, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/07/Lumi-Gloss.png', '["https://colorpluscosmetics.com/wp-content/uploads/2026/07/Lumi-Gloss.png"]'::jsonb, NULL, '[]'::jsonb, '["gloss","lip gloss","non-sticky lip gloss"]'::jsonb, TRUE, FALSE),
    ('Bellaoggi Color Pump', 'bellaoggi-color-pump', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Bellaoggi', 'Bellaoggi Color Pump lipstick delivers richly pigmented colour in a smooth jelly texture with a non-sticky, high-shine finish. From vibrant nudes to bold berry reds, this long-lasting lipstick glides on for precise, smudge-proof application', 'Bellaoggi Color Pump lipstick is formulated to deliver bold, richly pigmented colour in every swipe. With shades ranging from vibrant nudes to striking berry reds, this lipstick offers true-to-tone colour payoff that stands out beautifully, even on darker complexions.

Its bold yet supple jelly texture glides on effortlessly, adhering smoothly to the lips for a flawless, smoothing effect. Lips appear wrapped in a plastic-smooth film of pure, rich colour, finished with a radiance that’s genuinely unrivalled.

Housed in Bellaoggi’s sleek, fashion-forward Stylo packaging, this lipstick adds a touch of extravagance to any makeup collection, capturing a playful yet elegant spirit made for bold, confident femininity.

Key Features:

Highly Pigmented — intense colour payoff in one swipe

Precise Application — no smudge, clean lines every time

Jelly Texture — lightweight, comfortable, non-sticky feel

Super Shiny Finish — high-gloss radiance that lasts

Long-Lasting Wear — colour that stays vibrant all day

How to Use:

Start at the upper edge of the lips from the centre, then glide along the contour to shape as desired.', 2350, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/07/Color-Pump-CONFIDENCE.png', '["https://colorpluscosmetics.com/wp-content/uploads/2026/07/Color-Pump-CONFIDENCE.png"]'::jsonb, 'Bellaoggi Shades', '["001 CONFIDENCE","002 HONEY WAFFLES","003 CHERRY COLA","004 CHELSEA GIRL","005 BOSSY LADY","006 BERRY POWER"]'::jsonb, '["Color Pump","glossy lipstick","lipstick","Long Lasting Lipstick"]'::jsonb, TRUE, FALSE),
    ('Loreal Bonjour Sunshine', 'loreal-bonjour-sunshine', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Loreal', 'Get a natural, sun-kissed glow all year round with L’Oréal Bonjour Sunshine Liquid Bronzer. Its lightweight gel texture blends effortlessly, delivering a warm, radiant finish while keeping your skin hydrated for up to 24 hours. With SPF 22', 'Wake up your skin with a healthy, sun-kissed glow using L’Oréal Bonjour Sunshine Liquid Bronzer. Designed with a lightweight gel texture, this innovative bronzer provides an instant bronze effect without any self-tanning ingredients, making it perfect for daily use.

You can apply it all over your face for a soft, radiant glow or use it to sculpt and contour your natural features. The universal shade adapts beautifully to all skin tones, giving a natural, warm finish that mimics a subtle sun exposure.

Enriched with coconut extract, the formula not only enhances your complexion but also keeps your skin moisturized for up to 24 hours. With added SPF 22, it offers light sun protection, making it an ideal addition to your everyday makeup routine.', 1150, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/03/Loreal-Paris-Bonjour-Sunshine.png', '["https://colorpluscosmetics.com/wp-content/uploads/2026/03/Loreal-Paris-Bonjour-Sunshine.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Cetaphil Moisturizing Cream Ultimate', 'cetaphil-moisturizing-cream-ultimate', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Cetaphil', 'Rich, long-lasting hydration cream that soothes and protects dry, sensitive skin. Lightweight, non-irritating formula with prebiotic aloe keeps skin soft and comfortable for up to 48 hours.', 'Cetaphil Moisturizing Cream Ultimate is designed to deeply hydrate and protect dry, sensitive skin. It provides up to 48 hours of continuous moisture, helping restore the skin’s natural barrier while giving instant relief from dryness and tightness.

Formulated with prebiotic aloe and antioxidants, it supports healthy skin and defends against common signs of sensitivity such as irritation, roughness, and weakened skin barrier. The gentle, hypoallergenic formula is free from parabens and fragrance, making it suitable for everyday use without causing irritation.

Its non-comedogenic texture absorbs easily without clogging pores, leaving skin smooth, soft, and well-nourished.', 3050, 3050, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2026/03/Cetaphil-Moisturizing-Cream-Ultimate-566g.png', '["https://colorpluscosmetics.com/wp-content/uploads/2026/03/Cetaphil-Moisturizing-Cream-Ultimate-566g.png"]'::jsonb, 'Size', '["453g","566g"]'::jsonb, '["Daily Face Moisturizer"]'::jsonb, TRUE, FALSE),
    ('LA Colors Gel Eyeliner', 'la-colors-gel-eyeliner', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'LA Colors', 'L.A. Colors Gel Eyeliner offers bold color with a creamy, gel-like finish. It glides smoothly without tugging, delivers long-lasting, smudge-proof wear, and can be sharpened for precise lines or blended for a smoky look. Available in classi', 'L.A. Colors Gel Eyeliner combines the control of a pencil with the rich intensity of a gel. Its smooth, creamy texture glides effortlessly on the eyelids, allowing you to create sharp lines, bold wings, or soft smoky looks before it sets. Once dry, the formula becomes smudge-proof and long-wearing, making it ideal for day-to-night makeup that stays put without fading.

With a selection of metallic, neon, and classic shades, this eyeliner lets you match your mood, elevate simple looks, or experiment with creative styles. The plastic pencil is easily sharpenable, ensuring a precise tip every time. Affordable, pigmented, and versatile, it’s a must-have for anyone who loves long-lasting and impactful eye makeup.', 325, 290, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/LA-COLORS-GEL-EYELINER.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/LA-COLORS-GEL-EYELINER.png"]'::jsonb, NULL, '[]'::jsonb, '["Eyeliner","Gel Eyeliner"]'::jsonb, TRUE, TRUE),
    ('Skin1004 Tea-Trica Purifying Toner 210ml', 'skin1004-tea-trica-purifying-toner-210ml', '71120360', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'Skin1004 Tea-Trica Purifying Toner is a refreshing exfoliating toner for oily and acne-prone skin. Formulated with Tea Tree, Pine Complex, and soothing Centella, it helps remove dead skin cells, control excess sebum, and calm irritation for', 'Skin1004 Tea-Trica Purifying Toner is a gentle yet effective toner designed to purify oily and blemish-prone skin. Powered by Tea Tree Leaf Water and Pine Tree Complex, it works to reduce inflammation, treat breakouts, and protect the skin from bacterial infection. Its plant-based CS-Sebum Cleaner controls oil production, while BHA deeply exfoliates and unclogs pores, removing dead skin cells and impurities. With added Centella Asiatica extract, the toner soothes irritation and strengthens sensitive skin. Dermatologically tested to be non-comedogenic and hypoallergenic, it leaves your skin refreshed, balanced, and visibly clearer without irritation.', 1950, 1950, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/skin1004-toner-210ml-tea-trica-purifying-toner.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/skin1004-toner-210ml-tea-trica-purifying-toner.png"]'::jsonb, NULL, '[]'::jsonb, '["Purifying","toner"]'::jsonb, TRUE, FALSE),
    ('Loreal Infallible 24H Oil Killer High Coverage Compact Powder', 'loreal-infallible-24h-oil-killer-high-coverage-compact-powder', '71104160', (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Loreal', 'L’Oréal Infallible 24H Oil Killer High Coverage Compact Powder provides all-day oil control with a smooth, matte finish. Lightweight, water-proof, heat-proof, and non-comedogenic, it blurs pores, lightens dark spots, and offers SPF32 protec', 'Achieve a flawless, matte complexion with L’Oréal Infallible 24H Oil Killer High Coverage Compact Powder. Specially designed for all-day oil control, this powder delivers a smooth, perfecting finish while keeping your skin comfortable and breathable—even under a mask. Powered by micro-pigments, it blurs pores and helps lighten dark spots for a radiant, even-toned look.

Its lightweight formula is water-proof, heat-proof, and humidity-proof, ensuring long-lasting wear in any condition. With low transfer on masks and SPF32, PA +++ protection, it safeguards your skin from sun damage while maintaining a fresh matte appearance. Suitable for all skin types, particularly oily and sensitive skin, this non-comedogenic compact powder is your perfect everyday companion for a flawless, shine-free look.', 1350, 1350, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Loreal-paris-infallible-oil-killer-powder-95.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Loreal-paris-infallible-oil-killer-powder-95.png"]'::jsonb, 'Shade', '["123 Natural Vanilla","128 natural Buff","240 Natural Honey","95 Light Linen","Radiant Sand 250"]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('SKIN1004 Madagascar Centella Cream – 75ML', 'skin1004-madagascar-centella-cream-75ml', '71120361', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'SKIN1004 Madagascar Centella Cream – 75ML is a lightweight, soothing moisturizer enriched with Madagascar Centella Asiatica and plant-based ceramides. It calms irritated skin, strengthens the skin barrier, and delivers lasting hydration for', 'Experience the ultimate skin-soothing care with SKIN1004 Madagascar Centella Cream – 75ML. This potent moisturizer is formulated with the healing power of Madagascar Centella Asiatica, known for calming irritation and promoting a healthy complexion. Infused with four types of plant-based ceramides, it helps strengthen your skin barrier and lock in essential moisture, preventing dryness and sensitivity. Its lightweight, non-greasy texture absorbs quickly, leaving your skin smooth, soft, and nourished without any heavy residue. Free from parabens, sulfates, artificial fragrances, and harsh chemicals, this cream is gentle enough for all skin types, including sensitive skin, making it a perfect addition to your daily skincare routine.', 2150, 2150, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Ski-1004-Centella-Cream.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Ski-1004-Centella-Cream.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Bella Vita Luxury Rose Woman Perfume for Women', 'bella-vita-luxury-rose-woman-perfume-for-women', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Bella Vita', 'Bella Vita Luxury Rose Woman Perfume is a graceful blend of floral and woody notes that celebrates femininity, charm, and romance. Its captivating rose essence leaves an irresistible scent that lingers all day, defining timeless elegance.', 'Rose Woman by Bella Vita Luxury captures the true spirit of love and timeless romance. Crafted with elegant floral and sensual woody tones, this perfume exudes sophistication and grace. The heart of rich roses blends beautifully with subtle musk and amber, creating a warm, lasting trail that reflects confidence and charm. Perfect for every occasion, this fragrance complements the modern woman who embraces elegance and emotion in every moment.', 1115, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Rose-Women.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Rose-Women.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Bella Vita Luxury HOT Mess Woman Perfume &#8211; 100ml', 'bella-vita-luxury-hot-mess-woman-perfume-100ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Bella Vita', 'Bella Vita Luxury Hot Mess Woman Perfume is a bold and playful fragrance that blends citrus mandarin, exotic roses, and sensual musk. Perfect for confident women who love to turn heads effortlessly.', 'Bella Vita Luxury Hot Mess Woman Perfume is made for the unapologetically confident woman who embraces her chaotic charm and owns every room she walks into. This fragrance opens with a vibrant burst of citrus mandarin and passionfruit, leading into a heart of elegant jasmine and rose that adds a flirty floral touch. The base of warm musk and vanilla lingers beautifully, giving you that irresistible allure all day long. A perfect mix of floral, fruity, and sensual notes — it’s your go-to scent for date nights, parties, or anytime you want to feel bold, beautiful, and effortlessly hot.', 1435, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Hot-Mess-Women.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Hot-Mess-Women.png"]'::jsonb, NULL, '[]'::jsonb, '["women perfume","womens fragrances"]'::jsonb, TRUE, FALSE),
    ('Bella Vita Luxury SKAI Aquatic Unisex Perfume &#8211; 100ml', 'bella-vita-luxury-skai-aquatic-unisex-perfume-100ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Bella Vita', 'Bella Vita Luxury SKAI Aquatic Unisex Perfume brings a wave of freshness that lasts all day. With energising citrus top notes, a refreshing marine heart, and a confident woody base, this perfume is perfect for anyone who loves a clean, subt', 'Dive into freshness with Bella Vita Luxury SKAI Aquatic Unisex Perfume — a fragrance that captures the calm and confidence of the ocean breeze. The scent opens with invigorating notes of Bergamot and Coriander, setting a bright and lively tone. At its heart, marine and pink pepper notes bring a crisp, refreshing vibe that feels effortlessly modern. The base of Ambergris and woody accords adds depth, warmth, and long-lasting sophistication. Perfect for both men and women, SKAI Aquatic is your everyday signature scent — subtle, confident, and timeless.', 1115, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Skai-Aquatic.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Skai-Aquatic.png"]'::jsonb, NULL, '[]'::jsonb, '["unisex fragrances","unisex perfume"]'::jsonb, TRUE, FALSE),
    ('Bella Vita Luxury CEO Woman Perfume for Women', 'bella-vita-luxury-ceo-woman-perfume-for-women', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Bella Vita', 'CEO Woman by Bella Vita Luxury is a bold and elegant perfume for women who embrace confidence and sophistication. With warm notes of musk, leather, tonka, and vanilla, this long-lasting fragrance keeps you fresh and empowered all day.', 'CEO Woman Perfume by Bella Vita Luxury is crafted for women who lead with confidence and grace. This captivating fragrance blends subtle hints of musk with earthy tones of leather, tonka, and vanilla, creating a perfect balance of strength and sensuality. Designed to last throughout the day, its rich aroma keeps you feeling fresh, inspired, and ready to take on any challenge. Whether for work or an evening out, CEO Woman adds a refined and empowering touch to your everyday style.', 1115, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-CEO-Women.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-CEO-Women.png"]'::jsonb, NULL, '[]'::jsonb, '["women fragrance","women perfume","womens perfume"]'::jsonb, TRUE, FALSE),
    ('Bella Vita Luxury Date Perfume for Women', 'bella-vita-luxury-date-perfume-for-women', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Bella Vita', 'DATE Woman by Bella Vita Luxury is a romantic perfume crafted for unforgettable moments. With notes of pink pepper, red fruits, jasmine, and vanilla, it blends floral warmth with soft sweetness for a lasting impression.', 'DATE Woman by Bella Vita Luxury is a fragrance that captures the essence of love and timeless romance. Opening with the vibrant notes of Pink Pepper and Red Fruits, it draws you in with a playful charm. The heart reveals a graceful bouquet of Jasmine, Orange Blossom, and Violet—delicate yet deeply alluring. As the scent settles, base notes of Moss, Musk, and Powdery Vanilla create a soft, sensual trail that lingers beautifully on the skin. IFRA-certified and crafted with imported oils, this long-lasting perfume is safe to wear and perfect for special evenings or intimate moments.', 1115, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Date-Women.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/11/Bellavitta-Date-Women.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Fairy Skin Premium Tinted Sunscreen SPF 50 PA+++, 50ml', 'fairy-skin-premium-tinted-sunscreen-spf-50-pa-50ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Fairy', 'Fairy Skin Premium Tinted Sunscreen SPF 50 PA+++ combines sun protection, hydration, and a natural tone-up effect in one lightweight formula. It delivers 0% white cast, a smooth non-sticky texture, and deep skin nourishment — all at an affo', 'Experience flawless protection and radiance with Fairy Skin Premium Tinted Sunscreen SPF 50 PA+++. This all-in-one formula provides high sun protection while keeping your skin hydrated and bright. Designed with a lightweight, non-sticky texture, it blends seamlessly into the skin without leaving any white cast — just a smooth, natural tone-up finish.

Perfected over nearly a year of research, this sunscreen offers a balance of protection, hydration, and whitening benefits, rigorously tested and certified with SPF 50 by the DAISO Ultraviolet Transmittance Analyzer. Beyond its cosmetic glow, it actively shields your skin from harmful UV rays, helping prevent premature aging, dark spots, and sun-related skin damage.

Enjoy premium skincare protection and a radiant finish with Fairy Skin — where affordability meets quality in every drop.', 1295, 1295, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Fairy-Tinted.jpeg', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Fairy-Tinted.jpeg"]'::jsonb, NULL, '[]'::jsonb, '["Tinted Sunscreen"]'::jsonb, TRUE, FALSE),
    ('Banana Boat Sport Ultra Spray SPF 100', 'banana-boat-sport-ultra-spray-spf-100', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Banana', 'A high-performance SPF 100 sunscreen spray designed for active lifestyles. The Banana Boat Sport Ultra Spray provides powerful UVA/UVB protection that stays on through sweat and water—lightweight, non-greasy, and fast-absorbing for worry-fr', 'The Banana Boat Sport Ultra Spray SPF 100 is built for those who live life outdoors. Its advanced, lightweight formula offers clinically proven UVA/UVB protection with up to 80 minutes of water and sweat resistance, ensuring reliable defense even during intense activities. The fast-absorbing, non-greasy spray won’t run into your eyes, keeping you comfortable while you stay active. Recommended by the Skin Cancer Foundation, this breathable sunscreen keeps your skin protected and your fun uninterrupted—ideal for sports, beach days, and any outdoor adventure.', 1495, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Banana-Boat.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Banana-Boat.png"]'::jsonb, NULL, '[]'::jsonb, '["sunscreen spray","Water Resistant Sunscreen"]'::jsonb, TRUE, FALSE),
    ('Skin1004 Tone Brightening Capsule Ampoule 30ml', 'skin1004-tone-brightening-capsule-ampoule-30ml', '71120353', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'A daily-use brightening ampoule packed with 4% Niacinamide, 2% Tranexamic Acid, and encapsulated Madewhite™ to help fade dark spots, even skin tone, and give a healthy, radiant glow. Suitable for normal to sensitive skin.', 'The Skin1004 Tone Brightening Capsule Ampoule (30ml) delivers powerful yet gentle brightening care in a lightweight, essence-like texture. Formulated with 4% Niacinamide and 2% Tranexamic Acid, it works to visibly reduce dark spots, dullness, and discoloration for a more even complexion. The Madewhite™ micro-capsules, a patented natural ingredient, melt into the skin to enhance brightness and promote a soft, luminous glow. Powered by OIL-IN-WATER-GEL technology, it provides deep hydration without any stickiness. Perfect for normal, combination, and sensitive skin, this ampoule leaves your skin calm, smooth, and radiant every day.', 1150, 1150, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin1004-Ampoule-30ml-Tone-Brightening.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin1004-Ampoule-30ml-Tone-Brightening.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, TRUE),
    ('Skin1004 Tone Brightening Capsule Ampoule 50ml', 'skin1004-tone-brightening-capsule-ampoule-50ml', '71120354', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'A lightweight brightening ampoule infused with 4% Niacinamide, 2% Tranexamic Acid, and encapsulated Madewhite™ to visibly reduce dark spots, even skin tone, and enhance natural radiance—perfect for daily use on normal to sensitive skin.', 'The Skin1004 Tone Brightening Capsule Ampoule is a gentle yet powerful daily-use formula designed to restore skin clarity and brightness. Enriched with 4% Niacinamide and 2% Tranexamic Acid, it helps fade dark spots, reduce discoloration, and prevent uneven pigmentation. Its patented Madewhite™ capsules burst upon application, releasing natural brightening ingredients that leave your skin glowing and hydrated. The OIL-IN-WATER-GEL technology ensures deep, lasting moisture with a refreshing, non-sticky finish. Suitable for normal, sensitive, and combination skin, this ampoule delivers calm, radiant, and even-toned skin with every use.', 1650, 1650, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin1004-Ampoule-50ml-Tone-Brightening.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin1004-Ampoule-50ml-Tone-Brightening.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Loreal Paris Infallible Full Wear Concealer', 'loreal-paris-infallible-full-wear-concealer', '71103228', (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Loreal', 'A high-coverage, long-wearing concealer that hides dark circles, blemishes, and imperfections with a natural matte finish. L’Oréal Paris Infallible Full Wear Concealer delivers up to 24-hour wear without caking or creasing—perfect for conce', 'L’Oréal Paris Infallible Full Wear Concealer is your go-to solution for high-impact coverage with a lightweight, blendable formula. Designed to conceal dark circles, blemishes, redness, and uneven skin tone, this full-coverage concealer provides a smooth, airbrushed finish that lasts all day without settling into fine lines or creasing.

With its multi-use capabilities, this concealer does more than cover—it also works beautifully for brightening, contouring, and highlighting. Its creamy texture glides effortlessly onto the skin and blends seamlessly, whether you use a brush, sponge, or your fingertips.

Powered by long-lasting pigments and advanced technology, the Infallible Full Wear Concealer adapts to your skin tone for a natural, undetectable finish. The large doe-foot applicator makes targeted application quick and easy, allowing you to build coverage where you need it most.

Visible results: A smooth, even complexion, visibly brighter under-eyes, and reliable all-day wear. Whether you’re going for a no-makeup look or a full-glam finish, this concealer is a must-have in any makeup routine.', 1450, 1450, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Loreal-Paris-loreal-infallible-full-wear-concealer-314.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Loreal-Paris-loreal-infallible-full-wear-concealer-314.png"]'::jsonb, 'Shade', '["312","314","317"]'::jsonb, '["concealer","full wear concealer"]'::jsonb, TRUE, FALSE),
    ('CeraVe Foaming Facial Cleanser 473ml (Made in France)', 'cerave-foaming-facial-cleanser-473ml-made-in-france', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'CeraVe', 'A dermatologist-developed foaming cleanser made in France that deeply cleanses normal to oily skin without stripping moisture. Formulated with ceramides, niacinamide, and hyaluronic acid to refresh, balance, and protect the skin barrier.', 'CeraVe Foaming Facial Cleanser 473ml (Made in France) is a refreshing gel-to-foam face wash designed for normal to oily skin. Developed with dermatologists, this cleanser effectively removes excess oil, dirt, and makeup while helping to maintain the skin’s natural moisture balance.

Its formula is enriched with three essential ceramides to support the skin barrier, niacinamide to calm and soothe, and hyaluronic acid to retain hydration. Unlike harsh cleansers that can leave the skin feeling dry or tight, this non-drying formula cleanses thoroughly without disrupting the protective barrier.

Made in France, this foaming cleanser is fragrance-free, non-comedogenic, and suitable for daily use—leaving the skin feeling clean, fresh, and balanced.', 2850, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cerave-Foaming-Cleanser.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cerave-Foaming-Cleanser.png"]'::jsonb, NULL, '[]'::jsonb, '["foaming facial cleanser"]'::jsonb, TRUE, FALSE),
    ('CeraVe Hydrating Cleanser 473ml (Made in France)', 'cerave-hydrating-cleanser-473ml-made-in-france', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'CeraVe', 'A gentle, non-foaming cleanser made in France that cleanses, hydrates, and helps restore the skin barrier with ceramides and hyaluronic acid—perfect for normal to dry skin.', 'Developed with dermatologists and made in France, the CeraVe Hydrating Facial Cleanser (473ml) is a gentle, non-foaming formula designed to effectively cleanse the skin while preserving its natural moisture balance.

Infused with three essential ceramides (1, 3, 6-II) and hyaluronic acid, it works to hydrate and help restore the skin’s protective barrier without over-stripping or causing dryness. This fragrance-free, non-comedogenic cleanser is ideal for normal to dry skin, leaving it feeling clean, soft, and refreshed.

Whether used as part of your morning or evening routine, this French-made formula delivers trusted care with a focus on skin health and comfort.', 2850, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cerave-Hydrating-Cleanser.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cerave-Hydrating-Cleanser.png"]'::jsonb, NULL, '[]'::jsonb, '["facial cleanser","hydrating cleanser"]'::jsonb, TRUE, FALSE),
    ('Skin1004 Centella Ampoule &#8211; 100ml', 'skin1004-centella-ampoule-100ml', '71120427', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'A gentle, hydrating ampoule powered by 100% Centella Asiatica extract from Madagascar to calm, soothe, and restore sensitive or irritated skin.', 'Skin1004 Centella Ampoule is a lightweight yet powerful skin treatment formulated with 100% Centella Asiatica extract sourced from Madagascar. Known for its soothing, calming, and hydrating properties, this ampoule is ideal for sensitive, troubled, or redness-prone skin types. It helps support the skin’s natural moisture barrier while delivering a fresh, non-sticky finish. Whether your skin is stressed, reactive, or simply in need of balance, this ampoule provides a clean and effective solution to restore comfort and health.', 2450, 2450, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin-1004-Ampoule-100ml.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Skin-1004-Ampoule-100ml.png"]'::jsonb, NULL, '[]'::jsonb, '["centella ampoule"]'::jsonb, TRUE, FALSE),
    ('Beauty Of Joseon Dynasty Cream &#8211; 100 ml', 'beauty-of-joseon-dynasty-cream-100-ml', '71120356', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Beauty of Joseon', 'Beauty of Joseon Dynasty Cream (100ml) is a luxurious moisturizer infused with Rice Bran Water, Ginseng Root Water, Squalane, and Niacinamide. It delivers deep hydration, balances oil and moisture, and leaves your skin with a soft, healthy', 'Rediscover timeless Korean beauty with the Beauty of Joseon Dynasty Cream – 100ml, an upgraded version of the brand’s signature moisturizer. Celebrated for its rich, creamy texture and nourishing formula, this luxurious cream provides long-lasting hydration and a naturally radiant finish.

Formulated with 29% Rice Bran Water, a traditional “Beauty Water” from the Joseon era, it nourishes the skin with amino acids, minerals, and Vitamin E to maintain moisture and softness. 5% Ginseng Root Water revitalizes and energizes the skin with rich saponins, while 2% Squalane helps balance oil and moisture, strengthening the skin’s natural barrier. 2% Niacinamide works to regulate sebum production, even skin tone, and promote a luminous complexion.

This all-in-one cream deeply moisturizes, soothes, and protects the skin from external stressors while leaving a subtle, dewy glow that enhances your natural beauty. Suitable for all skin types, it layers perfectly under makeup or can be used alone for a healthy, radiant look.', 3150, 3150, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/BOJ-Dynasty-Cream.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/BOJ-Dynasty-Cream.png"]'::jsonb, NULL, '[]'::jsonb, '["korean beauty moisturising cream","moisturizing cream"]'::jsonb, TRUE, FALSE),
    ('Cetaphil Sun Spf 30 Very High Protection Light Gel 100ml', 'cetaphil-sun-spf-30-very-high-protection-light-gel-100ml', '71165465', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Cetaphil', 'Cetaphil Sun SPF 30+ Very High Protection Light Gel provides strong UVA/UVB protection for the face and body. Its lightweight, fast-absorbing, and water-resistant formula helps prevent skin pigmentation and premature aging—perfect for daily', 'Protect your skin every day with Cetaphil Sun SPF 30+ Very High Protection Light Gel, a dermatologist-tested sunscreen specially designed for sensitive skin. Offering high broad-spectrum protection against both UVA and UVB rays, it helps prevent sun-induced pigmentation, dark spots, and premature skin aging.

Formulated with photostable UV filters, this sunscreen ensures long-lasting protection even under strong sunlight. Its light gel texture absorbs quickly, leaving a non-greasy, matte finish that won’t clog pores. The formula is non-comedogenic, paraben-free, and fragrance-free, making it gentle and safe for all skin types.

Highly water-resistant, Cetaphil Sun SPF 30+ Light Gel is perfect for outdoor activities and everyday wear.

How to Use:

Apply generously to the face and body 15–20 minutes before sun exposure. Reapply every 2 hours or after swimming, sweating, or towel drying for continuous protection.', 1500, 1500, 1, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cetaphil-Sun-SPF-30.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Cetaphil-Sun-SPF-30.png"]'::jsonb, NULL, '[]'::jsonb, '["gel sunscreen","Sunscreen Gel"]'::jsonb, TRUE, FALSE),
    ('Derma Co 10% Cica &#8211; Glow Face Serum', 'derma-co-10-cica-glow-face-serum', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Derma', 'The Derma Co. 10% Cica Glow Face Serum delivers a radiant, even-toned complexion with the power of Cica Extract, Kojic Acid, and Tranexamic Acid. This lightweight, fast-absorbing serum deeply nourishes, fades dark spots, and gives your skin', 'Get ready to glow with The Derma Co. 10% Cica Glow Face Serum, a super-light, fast-absorbing formula designed to brighten and nourish your skin from within. Enriched with Cica Extract, it soothes and hydrates the skin while reducing redness and irritation. The powerful blend of Kojic Acid and Tranexamic Acid helps fade dark spots, even out skin tone, and control melanin production for a visibly radiant complexion.

Packed with antioxidants and anti-inflammatory properties, this serum protects your skin from free radical damage and promotes a smooth, healthy glow. Its non-greasy texture makes it perfect for daily use, leaving your skin soft, supple, and luminous—because glowing skin is always in season.', 950, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Derma-10-Cica-Glow-Face-Serum-30ml.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Derma-10-Cica-Glow-Face-Serum-30ml.png"]'::jsonb, NULL, '[]'::jsonb, '["Face Serum","Glow Serum","Serum"]'::jsonb, TRUE, FALSE),
    ('Derma Co 15% Vitamin C Face Serum &#8211; 30ml', 'derma-co-15-vitamin-c-face-serum-30ml', NULL, (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Derma', 'The Derma Co. 15% Vitamin C Face Serum brightens, firms, and hydrates your skin for a radiant, healthy glow. Enriched with Vitamin C, Niacinamide, Hyaluronic Acid, and Ceramides, it helps reduce open pores, smooth fine lines, and improve sk', 'Unveil your skin’s natural radiance with The Derma Co. 15% Vitamin C Face Serum, a powerful formula designed to brighten, firm, and deeply hydrate your skin. Infused with 15% Vitamin C, this serum helps reduce dullness, fade dark spots, and promote a more even skin tone. The synergistic blend of 5% Niacinamide, Hyaluronic Acid, Ferulic Acid, and Ceramides enhances skin texture, strengthens the barrier, and locks in moisture for long-lasting hydration.', 1275, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Derma-15-Vitamin-C-Face-Serum-30ml.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Derma-15-Vitamin-C-Face-Serum-30ml.png"]'::jsonb, NULL, '[]'::jsonb, '["Serum"]'::jsonb, TRUE, FALSE),
    ('Maybelline Blender Sponge', 'maybelline-blender-sponge', NULL, (SELECT id FROM public.product_categories WHERE slug = 'tools-accessories'), 'Maybelline', 'Makeup blending sponge for smooth, even foundation coverage and a natural, flawless finish.', 'The Maybelline Blender Sponge delivers seamless, even foundation application for a professional-looking finish. Designed to glide effortlessly over large areas and reach hard-to-access curves, it ensures your makeup blends perfectly every time. A must-have tool for achieving a smooth, flawless complexion.', 650, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/10/Maybelline-Blender.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/10/Maybelline-Blender.png"]'::jsonb, NULL, '[]'::jsonb, '["blender"]'::jsonb, TRUE, FALSE),
    ('Odbo Brow Styling & Setting Gel', 'odbo-brow-styling-setting-gel', NULL, (SELECT id FROM public.product_categories WHERE slug = 'tools-accessories'), 'Odbo', 'ODBO Brow Styling & Setting Gel shapes and sets your eyebrows for a natural, fluffy look. The clear gel keeps hairs in place all day and comes with a brush to style every strand with ease.', 'Achieve perfectly styled brows with ODBO Brow Styling & Setting Gel. This clear gel coats each hair to keep your eyebrows in a natural, fluffy shape all day long. It includes a precise eyebrow brush to style and separate every strand for a polished look. Easy to use, it ensures your brows stay in place while maintaining a soft, natural finish. Perfect alone or layered with a tinted brow mascara for added fullness.', 950, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/Odbo-Brow-Styling-and-setting-gel.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/Odbo-Brow-Styling-and-setting-gel.png"]'::jsonb, NULL, '[]'::jsonb, '["setting gel"]'::jsonb, TRUE, TRUE),
    ('L.A Girl Lip Mask', 'l-a-girl-lip-mask', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'L.A', 'L.A. Girl Lip Mask is a nourishing leave-on treatment that hydrates, softens, and smooths dry lips. Enriched with vitamins and natural oils, it leaves lips plump, revived, and comfortable all day or overnight.', 'Give your lips the care they deserve with the L.A. Girl Lip Mask, a hydrating treatment designed to restore softness and comfort. Infused with vitamin A, vitamin E, chia seed oil, sunflower seed oil, and jojoba seed oil, it deeply nourishes while sodium hyaluronate and tripeptide-1 help smooth fine lines and leave lips looking fuller. The non-sticky formula glides on easily with a flexible spatula applicator, making it perfect for use anytime — as a daytime balm or an overnight lip mask. Cruelty-free and paraben-free, this treatment ensures your lips feel healthy, hydrated, and cared for.', 695, 600, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/LA-Girl-Lip-Mask.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/LA-Girl-Lip-Mask.png"]'::jsonb, NULL, '[]'::jsonb, '["lip mask"]'::jsonb, TRUE, FALSE),
    ('L.A Girl Foundation Mixing Pigment', 'l-a-girl-foundation-mixing-pigment', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'L.A', 'Easily customize your foundation shade with L.A. Girl PRO.color Foundation Mixing Pigment. Designed to help you achieve your perfect match, this formula blends seamlessly with your foundation for a natural, flawless finish. Cruelty-free, ve', 'Finding the right foundation match doesn’t have to be a struggle anymore. The L.A. Girl PRO.color Foundation Mixing Pigment is specially formulated to adjust your foundation shade and undertone with ease, giving you a personalized finish every time. Its lightweight, blendable formula mixes smoothly without altering the foundation’s texture, ensuring a consistent, natural look. Ideal for refining undertones or balancing shades throughout the year, this pigment is cruelty-free, vegan, and paraben-free — a must-have for every makeup kit.', 1350, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/LA-GIRL-Foundation-Mixing-Pigment.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/LA-GIRL-Foundation-Mixing-Pigment.png"]'::jsonb, 'Shades', '["GLM711 White","GLM714 Blue"]'::jsonb, '["foundation","mixing pigment"]'::jsonb, TRUE, FALSE),
    ('LA Colors Lip Stain', 'la-colors-lip-stain', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'LA Colors', 'LA Colors Lip Stain gives a glossy tint with a fruity scent. Lightweight, hydrating, long-wearing, paraben-free, vegan, and cruelty-free.', 'Stain and shine in one swipe! The LA Colors Lip Stain gives your lips a glossy high-shine finish with a subtle, long-lasting tint. Available in 6 fruity scents, this lightweight formula hydrates while adding a kiss of color that stays put all day. Designed to be lip-loving and comfortable, it keeps your lips soft, fresh, and moisturized. Perfect for an effortless all-day look, this gloss-tint hybrid is paraben-free, vegan, and cruelty-free—making it a must-have for vibrant, glossy lips with a touch of care.', 350, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/Lip-Stain-Color-Tinting-Gloss-Hello-Melon-1.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/Lip-Stain-Color-Tinting-Gloss-Hello-Melon-1.png"]'::jsonb, 'Gloss Shades', '["CLG436 Hello Melon","CLG437 Raspberry Rush","CLG448 Tropical Punch","CLG450 Posh Peach"]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Victoria’s Secret Love Spell Shimmer Body Mist', 'victorias-secret-love-spell-shimmer-body-mist', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Victoria’s', 'Shine with every spritz. Love Spell Shimmer Body Mist blends iconic fragrance with a sparkling finish, leaving skin lightly scented and glowing.', 'Celebrate your radiant side with Victoria’s Secret Love Spell Shimmer Body Mist. This luminous mist combines the beloved Love Spell fragrance with a touch of shimmer, giving your skin a soft, sparkling glow. Perfect for every occasion, it layers beautifully with the matching Fragrance Lotion to create a long-lasting, irresistible scent. A shimmering twist on a signature classic—because every moment deserves a little sparkle.', 2200, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/Victoria-Secreat-Love-Spell-Shimmer-1.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/Victoria-Secreat-Love-Spell-Shimmer-1.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Victoria Secret’s Coconut Passion Shimmer Body Lotion', 'victoria-secrets-coconut-passion-shimmer-body-lotion', NULL, (SELECT id FROM public.product_categories WHERE slug = 'bath-body'), 'Victoria', 'Indulge in sunkissed radiance with Coconut Passion Shimmer Body Lotion. A sensual blend of coconut milk, sugared amber, and warm sand, wrapped in a touch of sparkle for skin that glows as beautifully as it feels.', 'Victoria’s Secret Coconut Passion Shimmer Body Lotion is your go-to for skin that feels soft, hydrated, and kissed by a subtle golden glow. This decadent gourmand fragrance opens with juicy blackberry and creamy coconut milk, blooms into notes of wild lily and raspberry blossom, and lingers with sugared amber and warm sand. Lightweight and silky, it nourishes your skin while leaving behind an irresistible shimmer. Perfect for adding a touch of luxury and radiance to your everyday routine.', 2500, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/Victoria-secreat-coconut-passion-shimmer.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/Victoria-secreat-coconut-passion-shimmer.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Skin1004 Centella Poremizing Fresh Ampoule (100ml)', 'skin1004-centella-poremizing-fresh-ampoule-100ml', '71120391', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Skin1004', 'A lightweight, non-comedogenic ampoule powered by Himalayan Pink Salt and 9 Peptides to clear pores, improve skin elasticity, and deliver refreshing hydration without stickiness.', 'The Skin1004 Centella Poremizing Fresh Ampoule (100ml) is a pore-refining skincare treatment designed to purify, hydrate, and strengthen the skin. Infused with Himalayan Pink Salt, rich in 80 natural minerals, this ampoule works deep within the pores to clear out impurities and reduce congestion. A blend of 9 skin-firming Peptides promotes collagen synthesis, helping to restore skin elasticity and tighten sagging pores. Its watery texture ensures fast absorption with minimal oil content, leaving the skin feeling refreshed, moisturized, and smooth—never sticky. Perfect for daily use, this ampoule delivers visible results for those struggling with enlarged pores, uneven texture, or loss of firmness, all while being gentle and non-comedogenic.', 2250, 2250, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/09/Centella-Poremizing-Fresh-Ampoule.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/09/Centella-Poremizing-Fresh-Ampoule.png"]'::jsonb, NULL, '[]'::jsonb, '["Serum"]'::jsonb, TRUE, FALSE),
    ('Anua Rice 70 Glow Milky Toner &#8211; 150ml', 'anua-rice-70-glow-milky-toner', '71120404', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Anua', 'A lightweight milky toner that hydrates, brightens uneven skin tone, balances sebum, and smoothens skin texture for a radiant, refreshed glow.', 'Refresh and hydrate your skin with Anua Rice 70 Glow Milky Toner, a lightweight milky toner that promotes a radiant, glowing complexion. This toner helps brighten uneven skin tone, balance excess sebum, and smooth rough skin texture. Its watery texture absorbs quickly, leaving your skin feeling refreshed and comfortable. Clinically tested, it provides immediate moisture after just one use and helps balance oily skin after 4 weeks.

Benefits:

• Brightens uneven skin tone

• Balances excess sebum

• Smoothens rough skin texture

• Lightweight, refreshing, and hydrating

How to Use:

• After cleansing, apply toner with a cotton pad or fingertips

• Gently pat all over the face until absorbed

• Use morning and night for best results', 2350, 2350, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/08/Untitled-design.jpg', '["https://colorpluscosmetics.com/wp-content/uploads/2025/08/Untitled-design.jpg"]'::jsonb, NULL, '[]'::jsonb, '["milk toner","toner"]'::jsonb, TRUE, FALSE),
    ('Anua Rice Ceramide 7 Hydrating Barrier Serum', 'anua-rice-ceramide-7-hydrating-barrier-serum', '71120405', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Anua', 'A gel serum that hydrates, soothes, and strengthens your skin’s moisture barrier while balancing sebum. Leaves skin refreshed and naturally glowing.', 'Keep your skin nourished, hydrated, and balanced with Anua Rice Ceramide 7 Hydrating Barrier Serum. This gentle gel serum strengthens the skin’s moisture barrier, soothes dryness, and leaves your skin looking naturally glowy. It also helps balance sebum production, keeping the skin healthy and refreshed. Clinically tested, users experienced a 45.4% improvement in skin moisture retention after 2 weeks and 63.9% after 4 weeks.

Benefits:

• Strengthens the skin’s moisture barrier

• Hydrates and soothes dry skin

• Balances sebum for healthier-looking skin

• Lightweight gel texture for fast absorption

How to Use:

• Apply a few drops to cleansed skin and gently pat with fingertips

• Use morning and night before oils or moisturizers

• During the day, follow with SPF 30+ for protection', 2250, 2250, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/08/Anua-Serum-50ml-Rice-7-Ceramide.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/08/Anua-Serum-50ml-Rice-7-Ceramide.png"]'::jsonb, NULL, '[]'::jsonb, '["Serum"]'::jsonb, TRUE, FALSE),
    ('Anua PDRN Hyaluronic Acid Capsule 100 Serum – 30ml', 'anua-pdrn-hyaluronic-acid-capsule-100-serum-30ml', '71120408', (SELECT id FROM public.product_categories WHERE slug = 'skincare'), 'Anua', 'A deeply moisturizing serum with PDRN, 11 types of Hyaluronic Acids, and hydrolyzed collagen. Improves skin texture, boosts hydration, strengthens the skin barrier, and reduces fine lines for a refreshed, radiant complexion.', 'Experience deep hydration and skin renewal with Anua PDRN Hyaluronic Acid Capsule 100 Serum. This advanced serum combines PDRN and 11 types of Hyaluronic Acids to improve overall skin texture, provide intense moisture, and restore skin vitality. Enriched with hydrolyzed collagen, it helps strengthen the skin barrier, preserve elasticity, and reduce the appearance of fine lines and wrinkles. Its lightweight, fluid texture absorbs quickly, leaving your skin refreshed, radiant, and plump. Free of artificial fragrance, it’s gentle and suitable for all skin types.

Benefits:

