    ('Bellaoggi Color Affair Eyeshadow Pearl & Shine', 'bellaoggi-color-affair-eyeshadow-pearl-shine', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Bellaoggi', 'Bellaoggi Color Affair Eyeshadow Pearl & Shine delivers a stunning frosted, glittery finish with ultra-bright, highly pigmented colors. Its silky-smooth formula blends effortlessly for all-day wear.', 'Illuminate your eyes with Bellaoggi Color Affair Eyeshadow Pearl & Shine! This mono eyeshadow features an ultra-refined frosted, glittery finish for a radiant, sparkling look. Its innovative formula, enriched with pearls, ensures a smooth, creamy texture that blends effortlessly while delivering intense pigmentation. Lightweight yet long-lasting, this eyeshadow stays vibrant all day, making it the perfect choice for a bold, dazzling eye look!', 1475, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/03/queen-grey.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/03/queen-grey.png"]'::jsonb, 'Bellaoggi Shades', '["35271-001 Cream Milk","35271-002 Marshmallow","35271-003 Dragonfly","35271-004 Queen Grey","35271-005 Girly Pink","35271-006 Wild Forest"]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Sheglam Color Bloom Liquid Blush', 'sheglam-color-bloom-liquid-blush', '71113136', (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Sheglam', 'Achieve a natural, radiant flush with Sheglam Color Bloom Liquid Blush! This lightweight gel-cream formula blends seamlessly, delivering highly pigmented, long-lasting matte color.', 'Get that effortless, rosy glow with Sheglam Color Bloom Liquid Blush! Packed with skin-loving ingredients, this lightweight gel-cream formula melts into your skin for a seamless, natural finish. The sponge-tip applicator ensures easy application, while the highly pigmented matte color keeps your cheeks looking fresh and plump all day. Plus, it’s cruelty-free and comes in recyclable packaging for a guilt-free beauty routine!', 1150, 1150, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/03/rose-ritual.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/03/rose-ritual.png"]'::jsonb, 'Blush Shade', '["Cutie Pie","Devoted","Love Cake","On Point","petal talk","Real Deal","Risky Business","Rose Ritual","Swipe Right"]'::jsonb, '[]'::jsonb, TRUE, FALSE),
