    ('Plum BodyLovin’ Hawaiian Rumba Eau de Parfum', 'plum-bodylovin-hawaiian-rumba-eau-de-parfum', NULL, (SELECT id FROM public.product_categories WHERE slug = 'fragrance'), 'Plum', 'Escape to a tropical paradise with Plum BodyLovin’ Hawaiian Rumba Eau de Parfum! This long-lasting, beachy fragrance blends exotic notes for a refreshing, summer vibe that lingers all day.', 'Get ready to vibe with the tropics! Plum BodyLovin’ Hawaiian Rumba Eau de Parfum is a long-lasting, beachy fragrance that transports you to sun-kissed shores with every spritz. Bursting with exotic, refreshing notes, this perfume keeps you feeling fresh and lively all day long. Whether you’re heading to the beach or just want to carry the summer with you, this scent is your perfect go-to for an instant tropical escape!', 470, NULL, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/03/plum-hawaain-rumba-2.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/03/plum-hawaain-rumba-2.png"]'::jsonb, NULL, '[]'::jsonb, '[]'::jsonb, TRUE, FALSE),
    ('Sheglam Skin Magnet High Coverage Foundation Stick', 'sheglam-skin-magnet-high-coverage-foundation-stick', '71120346', (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Sheglam', 'Achieve flawless, high-coverage skin with the Sheglam Skin Magnet High Coverage Foundation Stick. This portable, lightweight foundation provides a natural finish without caking, and its unique formula ensures long-lasting wear. Perfect for', 'Sheglam Skin Magnet High Coverage Foundation Stick is your ultimate travel companion for flawless skin. Designed with cutting-edge technology, this foundation offers full coverage with a natural, skin-like finish that won’t cake or settle into fine lines. Its breathable, lightweight formula is enriched with oils that provide a comfortable, long-lasting texture without melting off throughout the day. With its twist-to-reveal packaging, this foundation stick is the perfect choice for a quick touch-up, whether at home or on the go. Plus, it’s cruelty-free and recyclable, making it a great choice for conscious beauty lovers!', 1750, 1750, 25, 5, 'https://colorpluscosmetics.com/wp-content/uploads/2025/03/warm-vanilla.png', '["https://colorpluscosmetics.com/wp-content/uploads/2025/03/warm-vanilla.png"]'::jsonb, 'Shade', '["Acron","Bamboo","Butterscotch","Golden","Honey","Nude - Sheglam","Peach","Sand - Sheglam","Shell - Sheglam","Warm Vanilla","Wheat"]'::jsonb, '["foundation stick"]'::jsonb, TRUE, FALSE),
    ('Sheglam Good Grip Hydrating Primer', 'sheglam-good-grip-hydrating-primer-2', NULL, (SELECT id FROM public.product_categories WHERE slug = 'makeup'), 'Sheglam', 'Sheglam Good Grip Hydrating Primer is an oil and silicone-free primer with a refreshing gel texture that hydrates and smooths your skin. It absorbs quickly and locks in your makeup for long-lasting wear, keeping your base flawless all day.', 'Get ready for flawless base makeup with Sheglam Good Grip Hydrating Primer! This oil and silicone-free formula features a refreshing gel texture that hydrates, smooths, and leaves your skin feeling soft and moist. It’s designed to be quickly absorbed, creating the perfect canvas for your foundation while ensuring your makeup stays in place for hours.

