-- 3. VERIFY -----------------------------------------------------------------
SELECT c.name AS category, count(p.id) AS products
FROM public.product_categories c
LEFT JOIN public.products p ON p.category_id = c.id
GROUP BY c.name, c.display_order ORDER BY c.display_order;
